def read_ints():
    return list(map(int, input().split()))

n, m = read_ints()
edges = [read_ints() for _ in range(m)]

# Create adjacency list for the graph
adj_list = [[] for _ in range(n + 1)]
for u, v in edges:
    adj_list[u].append(v)
    adj_list[v].append(u)

# Find the degree of each vertex
degree = [len(adj_list[i]) for i in range(1, n + 1)]

# Check if the graph can be split into two vertex covers
def can_split_graph():
    # Find the vertex with the maximum degree
    max_degree_vertex = max(range(1, n + 1), key=lambda x: degree[x - 1])

    # If the maximum degree is greater than 2, it's impossible to split the graph
    if degree[max_degree_vertex - 1] > 2:
        return False

    # Initialize sets A and B
    A = set()
    B = set()

    # Assign vertices to A and B based on the degree
    for i in range(1, n + 1):
        if degree[i - 1] == 1:
            A.add(i)
        elif degree[i - 1] == 2:
            B.add(i)

    # Check if both A and B are vertex covers
    for u, v in edges:
        if (u in A and v in A) or (u in B and v in B):
            return False

    return True

# If it's possible to split the graph, output the vertex covers
if can_split_graph():
    A = set()
    B = set()

    # Assign vertices to A and B based on the degree
    for i, d in enumerate(degree):
        if d == 1:
            A.add(i + 1)
        elif d == 2:
            B.add(i + 1)

    print(len(A))
    print(" ".join(map(str, A)))
    print(len(B))
    print(" ".join(map(str, B)))
else:
    print(-1)
